/**
 * Turn a `git merge-base --is-ancestor` exit status into a reachability answer.
 *
 *   0    ancestor
 *   1    not an ancestor — a normal answer, not an error
 *   128  git could not resolve the SHA. When the object is absent entirely, that
 *        IS the lost-merge signature: #2273's merge commit lives only on a
 *        deleted branch, so a fresh clone has no such object. Reporting it as
 *        unreachable is the correct answer; re-throwing turned the daily sweep
 *        into a crash instead of a finding.
 *
 * Returns null when the caller should re-throw — a real git failure (a broken
 * repo, a bad ref) must stay loud rather than read as "not on main".
 *
 * @param {{status: number, objectExists: boolean}} probe
 * @returns {boolean|null}
 */
export function ancestorVerdict({ status, objectExists }) {
  if (status === 0) return true;
  if (status === 1) return false;
  if (status === 128 && !objectExists) return false;
  return null;
}

function objectExists(sha) {
  try {
    execFileSync("git", ["cat-file", "-e", `${sha}^{commit}`], {
      stdio: "ignore",
    });
    return true;
  } catch {
    return false;
  }
}

function makeIsAncestor(ref) {
  return (sha) => {
    let status = 0;
    try {
      execFileSync("git", ["merge-base", "--is-ancestor", sha, ref], {
        stdio: "ignore",
      });
    } catch (error) {
      status =
        error && typeof error === "object" && "status" in error
          ? Number(error.status)
          : Number.NaN;
      const verdict = ancestorVerdict({
        status,
        objectExists: objectExists(sha),
      });
      if (verdict === null) throw error;
      return verdict;
    }
    return true;
  };
}

