  it("reads exit 1 as not reachable — a normal answer", () => {
    expect(ancestorVerdict({ status: 1, objectExists: true })).toBe(false);
  });

  it("reads exit 128 on a MISSING object as not reachable — the #2273 shape", () => {
    expect(ancestorVerdict({ status: 128, objectExists: false })).toBe(false);
  });

  it("re-throws exit 128 when the object DOES exist — a real git failure", () => {
    // Must stay loud: a broken repo or bad ref must not read as "not on main".
    expect(ancestorVerdict({ status: 128, objectExists: true })).toBeNull();
  });

  it("re-throws an unrecognised status", () => {
    expect(ancestorVerdict({ status: 129, objectExists: false })).toBeNull();
    expect(ancestorVerdict({ status: Number.NaN, objectExists: false })).toBeNull();
  });
});

